CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDENTE',source TEXT,external_id TEXT,caption TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS queue(id INTEGER PRIMARY KEY AUTOINCREMENT,item_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'AGUARDANDO_APROVACAO',created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES items(id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,item_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS metrics(day TEXT PRIMARY KEY,sales REAL,commission REAL,orders INTEGER,clicks INTEGER,conversion REAL,published INTEGER,total_publications INTEGER);